diff --git a/mysql-test/suite/rpl/r/rpl_alter_user_empty_auth.result b/mysql-test/suite/rpl/r/rpl_alter_user_empty_auth.result
new file mode 100644
index 000000000000..19de4deacea7
--- /dev/null
+++ b/mysql-test/suite/rpl/r/rpl_alter_user_empty_auth.result
@@ -0,0 +1,52 @@
+include/master-slave.inc
+Warnings:
+Note	####	Sending passwords in plain text without SSL/TLS is extremely insecure.
+Note	####	Storing MySQL user name or password information in the connection metadata repository is not secure and is therefore not recommended. Please consider using the USER and PASSWORD connection options for START REPLICA; see the 'START REPLICA Syntax' in the MySQL Manual for more information.
+[connection master]
+#
+# Bug#38478657: ALTER USER with empty authentication data should not
+# expire passwords on replicas.
+#
+CREATE USER 'rpl_empty_auth_by'@'%'
+  IDENTIFIED WITH 'mysql_native_password' BY '';
+CREATE USER 'rpl_empty_auth_with'@'%'
+  IDENTIFIED WITH 'mysql_native_password' BY '';
+CREATE USER 'rpl_empty_auth_as'@'%'
+  IDENTIFIED WITH 'mysql_native_password' BY '';
+include/sync_slave_sql_with_master.inc
+ALTER USER 'rpl_empty_auth_by'@'%'
+  IDENTIFIED WITH caching_sha2_password BY '';
+ALTER USER 'rpl_empty_auth_with'@'%'
+  IDENTIFIED WITH caching_sha2_password;
+ALTER USER 'rpl_empty_auth_as'@'%'
+  IDENTIFIED WITH caching_sha2_password AS '';
+include/sync_slave_sql_with_master.inc
+SET @sql_log_bin_saved = @@sql_log_bin;
+SET sql_log_bin = 0;
+CREATE TABLE test.rpl_empty_auth_master
+SELECT user, host, plugin, authentication_string, password_expired
+FROM mysql.user
+WHERE user LIKE 'rpl_empty_auth_%'
+ORDER BY user;
+SET sql_log_bin = @sql_log_bin_saved;
+SET @sql_log_bin_saved = @@sql_log_bin;
+SET sql_log_bin = 0;
+CREATE TABLE test.rpl_empty_auth_slave
+SELECT user, host, plugin, authentication_string, password_expired
+FROM mysql.user
+WHERE user LIKE 'rpl_empty_auth_%'
+ORDER BY user;
+SET sql_log_bin = @sql_log_bin_saved;
+include/diff_tables.inc [master:test.rpl_empty_auth_master, slave:test.rpl_empty_auth_slave]
+DROP USER 'rpl_empty_auth_by'@'%', 'rpl_empty_auth_with'@'%',
+'rpl_empty_auth_as'@'%';
+SET @sql_log_bin_saved = @@sql_log_bin;
+SET sql_log_bin = 0;
+DROP TABLE test.rpl_empty_auth_master;
+SET sql_log_bin = @sql_log_bin_saved;
+include/sync_slave_sql_with_master.inc
+SET @sql_log_bin_saved = @@sql_log_bin;
+SET sql_log_bin = 0;
+DROP TABLE test.rpl_empty_auth_slave;
+SET sql_log_bin = @sql_log_bin_saved;
+include/rpl_end.inc
diff --git a/mysql-test/suite/rpl/t/rpl_alter_user_empty_auth.test b/mysql-test/suite/rpl/t/rpl_alter_user_empty_auth.test
new file mode 100644
index 000000000000..ae2b340beb7f
--- /dev/null
+++ b/mysql-test/suite/rpl/t/rpl_alter_user_empty_auth.test
@@ -0,0 +1,70 @@
+#
+# Verify that ALTER USER with empty authentication data replicates without
+# changing the account state.
+#
+
+--source include/not_have_privilege_checks_user.inc
+--source include/master-slave.inc
+
+--connection master
+--echo #
+--echo # Bug#38478657: ALTER USER with empty authentication data should not
+--echo # expire passwords on replicas.
+--echo #
+CREATE USER 'rpl_empty_auth_by'@'%'
+  IDENTIFIED WITH 'mysql_native_password' BY '';
+CREATE USER 'rpl_empty_auth_with'@'%'
+  IDENTIFIED WITH 'mysql_native_password' BY '';
+CREATE USER 'rpl_empty_auth_as'@'%'
+  IDENTIFIED WITH 'mysql_native_password' BY '';
+--source include/sync_slave_sql_with_master.inc
+
+--connection master
+ALTER USER 'rpl_empty_auth_by'@'%'
+  IDENTIFIED WITH caching_sha2_password BY '';
+ALTER USER 'rpl_empty_auth_with'@'%'
+  IDENTIFIED WITH caching_sha2_password;
+ALTER USER 'rpl_empty_auth_as'@'%'
+  IDENTIFIED WITH caching_sha2_password AS '';
+--source include/sync_slave_sql_with_master.inc
+
+--connection master
+SET @sql_log_bin_saved = @@sql_log_bin;
+SET sql_log_bin = 0;
+CREATE TABLE test.rpl_empty_auth_master
+SELECT user, host, plugin, authentication_string, password_expired
+FROM mysql.user
+WHERE user LIKE 'rpl_empty_auth_%'
+ORDER BY user;
+SET sql_log_bin = @sql_log_bin_saved;
+
+--connection slave
+SET @sql_log_bin_saved = @@sql_log_bin;
+SET sql_log_bin = 0;
+CREATE TABLE test.rpl_empty_auth_slave
+SELECT user, host, plugin, authentication_string, password_expired
+FROM mysql.user
+WHERE user LIKE 'rpl_empty_auth_%'
+ORDER BY user;
+SET sql_log_bin = @sql_log_bin_saved;
+
+--let $diff_tables=master:test.rpl_empty_auth_master, slave:test.rpl_empty_auth_slave
+--source include/diff_tables.inc
+
+--connection master
+DROP USER 'rpl_empty_auth_by'@'%', 'rpl_empty_auth_with'@'%',
+  'rpl_empty_auth_as'@'%';
+SET @sql_log_bin_saved = @@sql_log_bin;
+SET sql_log_bin = 0;
+DROP TABLE test.rpl_empty_auth_master;
+SET sql_log_bin = @sql_log_bin_saved;
+--source include/sync_slave_sql_with_master.inc
+
+--connection slave
+SET @sql_log_bin_saved = @@sql_log_bin;
+SET sql_log_bin = 0;
+DROP TABLE test.rpl_empty_auth_slave;
+SET sql_log_bin = @sql_log_bin_saved;
+
+--connection master
+--source include/rpl_end.inc
